<?php
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/security.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/portal.php';
requireRole(['Admin']);$users=$pdo->query("SELECT u.id,u.full_name,u.email FROM users u LEFT JOIN scholars s ON s.user_id=u.id WHERE u.role='User' AND u.is_active=1 AND s.id IS NULL ORDER BY u.full_name")->fetchAll();$programs=$pdo->query('SELECT id,name FROM scholarship_programs WHERE is_active=1 ORDER BY name')->fetchAll();$q=$pdo->query('SELECT u.full_name,s.student_number,p.name,s.status FROM scholars s JOIN users u ON u.id=s.user_id JOIN scholarship_programs p ON p.id=s.program_id ORDER BY u.full_name');$rows=[];foreach($q->fetchAll() as $r)$rows[]=[h($r['full_name']),h($r['student_number']),h($r['name']),h($r['status'])];portalStart('Manage Scholars','scholars.php');echo '<div class="portal-panel"><h2>Assign scholar</h2><form class="portal-form" method="post" action="../portal_action.php">'.csrf_field().'<input type="hidden" name="action" value="assign_scholar"><input type="hidden" name="back" value="scholars.php"><label>Student<select name="user_id" required>';foreach($users as $u)echo '<option value="'.h($u['id']).'">'.h($u['full_name'].' — '.$u['email']).'</option>';echo '</select></label><label>Program<select name="program_id" required>';foreach($programs as $p)echo '<option value="'.h($p['id']).'">'.h($p['name']).'</option>';echo '</select></label><label>Student number<input name="student_number" required maxlength="30"></label><button class="portal-button">Assign</button></form></div>';portalTable(['Student','Student number','Program','Status'],$rows);portalEnd();